+    file.slice(caseRoot.length + 1),
+    Object.fromEntries(
+      Object.entries(result.projects ?? {}).map(([root, project]) => [
+        root.slice(caseRoot.length + 1),
+        project,
+      ])
+    ),
+  ]);
+}
